#include "../math/check.hpp"

#include <model/part21.hpp>

#include <bit>
#include <cstdint>
#include <cstdio>
#include <string>

using namespace volt::model;
using part21::kind;

namespace
{
    // A file the way exporters write them: header, a complex unit, comments,
    // every kind of parameter.
    constexpr std::string_view sample = R"(ISO-10303-21;
HEADER;
/* Generated by hand for the tests */
FILE_DESCRIPTION(('A test file'),'2;1');
FILE_NAME('sample.step','2026-11-21T10:00:00',('Author'),(''),'Volt','Volt','');
FILE_SCHEMA(('AUTOMOTIVE_DESIGN { 1 0 10303 214 1 1 1 1 }'));
ENDSEC;
DATA;
#1=CARTESIAN_POINT('',(0.,1.5,-2.E-03));
#2 = DIRECTION ( 'axis' , ( 0. , 0. , 1. ) ) ;
#3=AXIS2_PLACEMENT_3D('',#1,#2,$);
#4=( LENGTH_UNIT() NAMED_UNIT(*) SI_UNIT(.MILLI.,.METRE.) );
#5=UNCERTAINTY_MEASURE_WITH_UNIT(LENGTH_MEASURE(1.E-07),#4,'distance_accuracy_value','confusion accuracy');
#6=PRODUCT('it''s','\X2\00E9\X0\t\X\E9 \S\i back\\slash','',());
#7=B_SPLINE_CURVE_WITH_KNOTS('',3,(#1,#1,#1,#1),.UNSPECIFIED.,.F.,.F.,(4,4),(0.,1.),.UNSPECIFIED.);
/* a comment
   over two lines */
#8=SOME_ENTITY(-42,+7,1.5E+20,"0FF",*,((1,2),(3,(4))),.T.,$);
#100=DERIVED_TEST(#3,#8);
ENDSEC;
END-ISO-10303-21;
)";

    bool same_value(const part21::parameter &a, const part21::parameter &b)
    {
        if (a.type() != b.type())
            return false;
        switch (a.type())
        {
        case kind::integer:
            return a.integer() == b.integer();
        case kind::real:
            return std::bit_cast<std::uint64_t>(a.number()) == std::bit_cast<std::uint64_t>(b.number());
        case kind::string:
        case kind::enumeration:
        case kind::binary:
            return a.text() == b.text();
        case kind::reference:
            return a.reference() == b.reference();
        case kind::list:
            if (a.size() != b.size())
                return false;
            for (std::size_t i = 0; i < a.size(); ++i)
            {
                if (!same_value(a[i], b[i]))
                    return false;
            }
            return true;
        case kind::typed:
            return a.type_name() == b.type_name() && same_value(a.inner(), b.inner());
        default:
            return true;
        }
    }

    bool same_entity(const part21::entity &a, const part21::entity &b)
    {
        if (a.id() != b.id() || a.is_complex() != b.is_complex() || a.part_count() != b.part_count())
            return false;
        for (std::size_t part = 0; part < a.part_count(); ++part)
        {
            if (a.name(part) != b.name(part) || !same_value(a.parameters(part), b.parameters(part)))
                return false;
        }
        return true;
    }

    bool same_file(const part21::file &a, const part21::file &b)
    {
        if (a.size() != b.size() || a.header_size() != b.header_size() || a.section_count() != b.section_count())
            return false;
        for (std::size_t i = 0; i < a.header_size(); ++i)
        {
            if (!same_entity(a.header(i), b.header(i)))
                return false;
        }
        for (std::size_t i = 0; i < a.size(); ++i)
        {
            if (!same_entity(a[i], b[i]))
                return false;
        }
        return true;
    }

    void parses_sample()
    {
        const auto parsed = part21::parse(sample);
        CHECK(parsed.has_value());
        if (!parsed)
        {
            std::fprintf(stderr, "%s\n", parsed.error().c_str());
            return;
        }
        const part21::file &file = *parsed;

        CHECK(file.size() == 9);
        CHECK(file.header_size() == 3);
        CHECK(file.find_header("FILE_SCHEMA").parameters()[0][0].text() == "AUTOMOTIVE_DESIGN { 1 0 10303 214 1 1 1 1 }");

        const part21::entity point = file.get(1);
        CHECK(point.name() == "CARTESIAN_POINT");
        CHECK(point.line() == 9);
        CHECK(point.parameters()[1].size() == 3);
        CHECK(point.parameters()[1][1].number() == 1.5);
        CHECK(point.parameters()[1][2].number() == -2.0e-3);
        CHECK(point.parameters()[1][0].is(kind::real));

        const part21::entity direction = file.get(2);
        CHECK(direction.name() == "DIRECTION");
        CHECK(direction.parameters()[0].text() == "axis");

        const part21::entity placement = file.get(3);
        CHECK(placement.parameters()[1].reference() == 1);
        CHECK(placement.parameters()[3].is(kind::omitted));

        // A complex instance: three types, each with its parameters.
        const part21::entity unit = file.get(4);
        CHECK(unit.is_complex());
        CHECK(unit.part_count() == 3);
        CHECK(unit.is("SI_UNIT") && unit.is("LENGTH_UNIT") && !unit.is("PLANE_ANGLE_UNIT"));
        CHECK(unit.parameters(*unit.find_part("NAMED_UNIT"))[0].is(kind::derived));
        const auto si = unit.parameters(*unit.find_part("SI_UNIT"));
        CHECK(si[0].text() == "MILLI" && si[1].text() == "METRE" && si[0].is(kind::enumeration));

        // Typed parameters.
        const part21::parameter measure = file.get(5).parameters()[0];
        CHECK(measure.is(kind::typed));
        CHECK(measure.type_name() == "LENGTH_MEASURE");
        CHECK(measure.value().number() == 1.0e-7);

        // Strings: doubled apostrophes, \X2\, \X\, \S\ and an escaped backslash.
        const part21::entity product = file.get(6);
        CHECK(product.parameters()[0].text() == "it's");
        CHECK(product.parameters()[1].text() == "\xC3\xA9t\xC3\xA9 \xC3\xA9 back\\slash");
        CHECK(product.parameters()[3].is(kind::list) && product.parameters()[3].size() == 0);

        const part21::parameter values = file.get(8).parameters();
        CHECK(values[0].integer() == -42);
        CHECK(values[1].integer() == 7 && values[1].is(kind::integer));
        CHECK(values[2].number() == 1.5e20);
        CHECK(values[3].is(kind::binary) && values[3].text() == "0FF");
        CHECK(values[4].is(kind::derived));
        CHECK(values[5].size() == 2 && values[5][1][1][0].integer() == 4);
        CHECK(values[6].logical(false));
        CHECK(!values[7].logical(false) && values[7].is(kind::omitted));
        CHECK(file.get(8).line() == 18);

        // Asking for what is not there is harmless.
        CHECK(values[99].is(kind::omitted));
        CHECK(values[0][3].is(kind::omitted));
        CHECK(values[0].text().empty());
        CHECK(!file.get(9999).valid());
        CHECK(file.get(100).valid());
    }

    void round_trips()
    {
        const auto first = part21::parse(sample);
        CHECK(first.has_value());
        if (!first)
            return;
        const std::string written = part21::write(*first);
        const auto second = part21::parse(written);
        CHECK(second.has_value());
        if (!second)
        {
            std::fprintf(stderr, "%s\n%s\n", second.error().c_str(), written.c_str());
            return;
        }
        CHECK(same_file(*first, *second));

        // And the text is stable from then on.
        CHECK(part21::write(*second) == written);
    }

    void formats_reals_and_strings()
    {
        CHECK(part21::format_real(1.0) == "1.");
        CHECK(part21::format_real(0.5) == "0.5");
        CHECK(part21::format_real(1e-7) == "1.E-07");
        CHECK(part21::format_real(-2.5e20) == "-2.5E+20");
        CHECK(part21::format_real(0.0) == "0.");

        // Every double reads back as itself.
        const double values[] = {0.1, 1.0 / 3.0, 25.4, 6.02214076e23, 1e-300, -123456.789, 5e-324};
        for (double value : values)
        {
            const std::string text = "ISO-10303-21;HEADER;ENDSEC;DATA;#1=X(" + part21::format_real(value) +
                                     ");ENDSEC;END-ISO-10303-21;";
            const auto file = part21::parse(text);
            CHECK(file.has_value() && file->get(1).parameters()[0].number() == value);
        }

        CHECK(part21::format_string("plain") == "'plain'");
        CHECK(part21::format_string("it's") == "'it''s'");
        CHECK(part21::format_string("a\\b") == "'a\\\\b'");
        CHECK(part21::format_string("\xC3\xA9t\xC3\xA9") == "'\\X2\\00E9\\X0\\t\\X2\\00E9\\X0\\'");
        CHECK(part21::format_string("\xF0\x9F\x99\x82") == "'\\X4\\0001F642\\X0\\'");
        CHECK(part21::format_string("tab\there") == "'tab\\X\\09here'");

        // Strings through a round trip, including what needs escaping.
        const std::string texts[] = {"", "''", "\\", "\xE2\x82\xAC 5", "\xF0\x9F\x99\x82 smile", "line\nbreak"};
        for (const std::string &text : texts)
        {
            const std::string source =
                "ISO-10303-21;HEADER;ENDSEC;DATA;#1=X(" + part21::format_string(text) + ");ENDSEC;END-ISO-10303-21;";
            const auto file = part21::parse(source);
            CHECK(file.has_value() && file->get(1).parameters()[0].text() == text);
        }
    }

    void tolerates_variations()
    {
        // Lower case keywords, CRLF line ends, a BOM, multiple DATA sections
        // with edition 3 parameters, sparse ids, a user-defined entity.
        const std::string text = "\xEF\xBB\xBFISO-10303-21;\r\nHEADER;\r\nfile_description((''),'2;1');\r\nENDSEC;\r\n"
                                 "DATA('one',('SCHEMA_A'));\r\n#1000000=point(.5,-.25,1E3);\r\nENDSEC;\r\n"
                                 "DATA;\r\n#7=!VENDOR_THING(#1000000,.t.);\r\nENDSEC;\r\nEND-ISO-10303-21;\r\n";
        const auto file = part21::parse(text);
        CHECK(file.has_value());
        if (!file)
        {
            std::fprintf(stderr, "%s\n", file.error().c_str());
            return;
        }
        CHECK(file->section_count() == 2);
        CHECK(file->get_section(0).parameters[0].text() == "one");
        CHECK(file->get_section(1).parameters.is(kind::omitted));
        CHECK(file->get(1000000).name() == "POINT");
        CHECK(file->get(1000000).parameters()[0].number() == 0.5);
        CHECK(file->get(1000000).parameters()[2].number() == 1000.0);
        CHECK(file->get(7).name() == "!VENDOR_THING");
        CHECK(file->get(7).parameters()[1].logical(false));
        CHECK(file->get(7).line() == 9);

        const auto again = part21::parse(part21::write(*file));
        CHECK(again.has_value() && same_file(*file, *again));
    }

    // Each must fail with an error naming the right line.
    void rejects_malformed()
    {
        struct bad
        {
            std::string_view text;
            std::string_view expected; // the start of the error
        };
        const bad cases[] = {
            {"", "line 1:"},
            {"HELLO;", "line 1:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(1,2;\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A('open);\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(1);\n#1=B(2);\nENDSEC;\nEND-ISO-10303-21;", "line 6:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(1);\n/* never closed\nENDSEC;", "line 6:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(1.E);\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(.T);\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(\"9F\");\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=();\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#0=A();\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(#);\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(1);\nENDSEC;\n", "line 7:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A(X(1,2));\nENDSEC;\nEND-ISO-10303-21;", "line 5:"},
            {"ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n#1=A('\\X2\\00E\\X0\\');\nENDSEC;\nEND-ISO-10303-21;",
             "line 5:"},
        };
        for (const bad &c : cases)
        {
            const auto result = part21::parse(c.text);
            CHECK(!result.has_value());
            if (!result)
            {
                const bool right_line = result.error().starts_with(c.expected);
                CHECK(right_line);
                if (!right_line)
                    std::fprintf(stderr, "  got: %s\n", result.error().c_str());
            }
        }

        // Nesting beyond the limit is an error, not a stack overflow.
        std::string deep = "ISO-10303-21;HEADER;ENDSEC;DATA;#1=A(";
        for (int i = 0; i < 100000; ++i)
            deep += '(';
        const auto result = part21::parse(deep);
        CHECK(!result.has_value());
    }

    // Truncations and flipped bits must give an error or a file, never a
    // crash or a hang.
    void survives_corruption()
    {
        const std::string original(sample);
        std::size_t parsed = 0;
        for (std::size_t length = 0; length + 1 < original.size(); length += 3)
        {
            if (part21::parse(std::string_view(original).substr(0, length)))
                ++parsed;
        }
        CHECK(parsed == 0); // every truncation loses the trailer

        std::uint32_t state = 12345;
        const auto random = [&] {
            state = state * 1664525u + 1013904223u;
            return state >> 8;
        };
        std::size_t survived = 0;
        for (int round = 0; round < 5000; ++round)
        {
            std::string copy = original;
            const int flips = 1 + static_cast<int>(random() % 4);
            for (int f = 0; f < flips; ++f)
            {
                const std::size_t at = random() % copy.size();
                copy[at] = static_cast<char>(copy[at] ^ static_cast<char>(1u << (random() % 8)));
            }
            const auto file = part21::parse(copy);
            if (file)
            {
                ++survived;
                // Whatever parsed must write and parse again.
                const auto again = part21::parse(part21::write(*file));
                CHECK(again.has_value());
            }
        }
        std::printf("corruption: %zu of 5000 damaged copies still parsed\n", survived);
    }
} // namespace

int main()
{
    parses_sample();
    round_trips();
    formats_reals_and_strings();
    tolerates_variations();
    rejects_malformed();
    survives_corruption();
    return volt::tests::result("model part21");
}
